using CertDesk.Common; using CertDesk.Models; using CertDesk.Services;
namespace CertDesk.Views;
public partial class AuditView:UserControl{ DataGridView grid=new(); DateTimePicker from=new(),to=new(); ComboBox act=new(){Width=180}; TextBox login=new(){Width=140}; public AuditView(CurrentUser u){InitializeComponent();Build();LoadData();} void Build(){BackColor=UiTheme.Light; Controls.AddRange(new Control[]{new Label{Text="Дата с",Left=15,Top=20},from,new Label{Text="по",Left=250,Top=20},to,new Label{Text="Действие",Left=480,Top=20},act,new Label{Text="Пользователь",Left=730,Top=20},login}); from.Left=70;from.Top=15;to.Left=275;to.Top=15;act.Left=550;act.Top=15;login.Left=820;login.Top=15; from.Value=DateTime.Today.AddMonths(-1); act.Items.Add(""); foreach(var a in AuditService.Actions()) act.Items.Add(a); act.SelectedIndex=0; var b=new Button{Text="Обновить",Left=970,Top=13,Width=110}; UiTheme.ApplyButtonStyle(b); grid.SetBounds(15,60,1050,560);grid.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Bottom;UiTheme.ApplyGridStyle(grid);Controls.AddRange(new Control[]{b,grid}); b.Click+=(_,__)=>LoadData();} void LoadData()=>grid.DataSource=AuditService.GetList(from.Value,to.Value,act.Text,login.Text);}
